-- Jóváhagyott saját ERP-anyagkezelés. Más alkalmazás és Auth változatlan.
begin;
create table erp.vendors(id uuid primary key,organization_id uuid not null references erp.organizations(id),name text not null check(length(btrim(name)) between 1 and 200),place text not null default '' check(length(place)<=500),active boolean not null default true,revision bigint not null default 1,unique(organization_id,id));
create table erp.materials(id uuid primary key,organization_id uuid not null references erp.organizations(id),name text not null check(length(btrim(name)) between 1 and 200),unit text not null check(length(btrim(unit)) between 1 and 30),vendor_id uuid,expected_price numeric(22,2),pack numeric(22,6) not null default 0,capacity numeric(22,6) not null default 0,active boolean not null default true,revision bigint not null default 1,unique(organization_id,id),unique(organization_id,id,unit),foreign key(organization_id,vendor_id) references erp.vendors(organization_id,id),check(expected_price>=0 and pack>=0 and capacity>=0));
create index material_vendor_fk on erp.materials(organization_id,vendor_id);
create index material_search_name on erp.materials(organization_id,name,id);
create index vendor_search_name on erp.vendors(organization_id,name,id);
create table erp.material_catalog_events(id uuid primary key,organization_id uuid not null references erp.organizations(id),actor_id uuid not null,actor_auth_id uuid not null,active_role text not null,kind text not null,target_id uuid,document jsonb not null,request_hash text not null,result jsonb not null,created_at timestamptz not null default clock_timestamp(),foreign key(organization_id,actor_id) references erp.persons(organization_id,id),check(pg_column_size(document)<524288));
create index material_catalog_actor_fk on erp.material_catalog_events(organization_id,actor_id);
create index material_catalog_scope on erp.material_catalog_events(organization_id,created_at desc,id desc);
create table erp.project_material_plans(id uuid primary key default gen_random_uuid(),organization_id uuid not null,project_id uuid not null,quote_id uuid not null,quote_version bigint not null,revision bigint not null default 0,created_by uuid not null,unique(organization_id,id),unique(organization_id,project_id),foreign key(organization_id,project_id) references erp.garden_projects(organization_id,id),foreign key(organization_id,quote_id,quote_version) references erp.quote_versions(organization_id,quote_id,version));
create index material_plan_quote_fk on erp.project_material_plans(organization_id,quote_id,quote_version);
create table erp.project_material_lines(id uuid primary key default gen_random_uuid(),organization_id uuid not null,plan_id uuid not null,material_id uuid,unit text not null,name text not null,source_kind text not null check(source_kind in('quote','extra')),source_key text,source_label text not null default '',installed_plan numeric(22,6) not null default 0,purchase_plan numeric(22,6) not null default 0,original_installed numeric(22,6) not null default 0,original_purchase numeric(22,6) not null default 0,owner text not null default 'crew' check(owner in('office','crew')),expected_price numeric(22,2),supplier text not null default '',capacity numeric(22,6) not null default 0,pack numeric(22,6) not null default 0,reason text not null default '',active boolean not null default true,linked_line_id uuid,revision bigint not null default 1,unique(organization_id,id),unique(plan_id,source_key),foreign key(organization_id,plan_id) references erp.project_material_plans(organization_id,id),foreign key(organization_id,material_id,unit) references erp.materials(organization_id,id,unit),foreign key(organization_id,linked_line_id) references erp.project_material_lines(organization_id,id),check(installed_plan>=0 and purchase_plan>=0 and capacity>=0 and pack>=0 and expected_price>=0));
create index material_line_master_fk on erp.project_material_lines(organization_id,material_id,unit);
create index material_line_link_fk on erp.project_material_lines(organization_id,linked_line_id);
create index material_line_plan on erp.project_material_lines(organization_id,plan_id,name,id);
create table erp.project_material_plan_versions(organization_id uuid not null,plan_id uuid not null,version bigint not null,quote_version bigint not null,document jsonb not null,actor_id uuid,actor_auth_id uuid,active_role text not null,created_at timestamptz not null default clock_timestamp(),primary key(organization_id,plan_id,version),foreign key(organization_id,plan_id) references erp.project_material_plans(organization_id,id));
create table erp.material_lots(id uuid primary key,organization_id uuid not null,line_id uuid not null,vendor_id uuid,place text not null default '',expected_price numeric(22,2),actual_price numeric(22,2),price_actor uuid,ordered numeric(22,6) not null default 0,depot numeric(22,6) not null default 0,transit numeric(22,6) not null default 0,site numeric(22,6) not null default 0,installed numeric(22,6) not null default 0,revision bigint not null default 0,created_by uuid not null,created_at timestamptz not null default clock_timestamp(),unique(organization_id,id),foreign key(organization_id,line_id) references erp.project_material_lines(organization_id,id),foreign key(organization_id,vendor_id) references erp.vendors(organization_id,id),foreign key(organization_id,created_by) references erp.persons(organization_id,id),check(ordered>=0 and depot>=0 and transit>=0 and site>=0 and installed>=0 and actual_price>=0 and expected_price>=0),check(length(place)<=500));
create index material_lot_line_fk on erp.material_lots(organization_id,line_id,id);
create index material_lot_vendor_fk on erp.material_lots(organization_id,vendor_id);
create index material_lot_creator_fk on erp.material_lots(organization_id,created_by);
create table erp.material_movements(id uuid primary key,organization_id uuid not null,lot_id uuid not null,actor_id uuid not null,actor_auth_id uuid not null,active_role text not null,kind text not null,work_date date not null,quantity numeric(22,6) not null default 0,delta jsonb not null,before_state jsonb not null,after_state jsonb not null,reverses_id uuid,reason text not null default '',request_hash text not null,result jsonb not null,created_at timestamptz not null default clock_timestamp(),unique(organization_id,id),unique(reverses_id),foreign key(organization_id,lot_id) references erp.material_lots(organization_id,id),foreign key(organization_id,actor_id) references erp.persons(organization_id,id),foreign key(organization_id,reverses_id) references erp.material_movements(organization_id,id),check(length(reason)<=4000));
create index material_move_reverse_fk on erp.material_movements(organization_id,reverses_id);
create index material_move_actor_fk on erp.material_movements(organization_id,actor_id);
create index material_move_history on erp.material_movements(organization_id,lot_id,created_at desc,id desc);
create table erp.material_notifications(id uuid primary key default gen_random_uuid(),organization_id uuid not null,project_id uuid not null,movement_id uuid not null,recipient_id uuid not null,read_at timestamptz,completed_at timestamptz,created_at timestamptz not null default clock_timestamp(),unique(movement_id,recipient_id),foreign key(organization_id,movement_id) references erp.material_movements(organization_id,id),foreign key(organization_id,recipient_id) references erp.persons(organization_id,id),foreign key(organization_id,project_id) references erp.garden_projects(organization_id,id));
create index material_note_move_fk on erp.material_notifications(organization_id,movement_id);
create index material_note_person_fk on erp.material_notifications(organization_id,recipient_id,created_at desc,id desc);
create index material_note_project_fk on erp.material_notifications(organization_id,project_id);
create table erp.material_cost_policy_versions(organization_id uuid not null references erp.organizations(id),version bigint not null,installed numeric(7,4) not null default 100,onsite numeric(7,4) not null default 70,offsite numeric(7,4) not null default 0,actor_id uuid not null,reason text not null default '',created_at timestamptz not null default clock_timestamp(),primary key(organization_id,version),foreign key(organization_id,actor_id) references erp.persons(organization_id,id),check(installed between 0 and 100 and onsite between 0 and 100 and offsite between 0 and 100));
create index material_policy_actor_fk on erp.material_cost_policy_versions(organization_id,actor_id);
do $$declare t text;begin foreach t in array array['vendors','materials','material_catalog_events','project_material_plans','project_material_lines','project_material_plan_versions','material_lots','material_movements','material_notifications','material_cost_policy_versions'] loop execute format('alter table erp.%I enable row level security',t);execute format('alter table erp.%I force row level security',t);execute format('revoke all on erp.%I from public,anon,authenticated,service_role',t);end loop;end$$;
create function erp_private.material_immutable() returns trigger language plpgsql set search_path='' as $$begin raise exception 'Az anyagkezelési előzmény megőrzött adat.' using errcode='42501';end$$;
do $$declare t text;begin foreach t in array array['material_catalog_events','project_material_plan_versions','material_movements','material_cost_policy_versions'] loop execute format('create trigger material_history before update or delete on erp.%I for each row execute function erp_private.material_immutable()',t);end loop;end$$;
create function erp_private.material_context(p_org uuid,p_actor uuid,p_session uuid,p_project uuid,p_role text) returns jsonb language plpgsql stable security definer set search_path='' as $$declare ctx jsonb;person uuid;begin
 if p_project is not null then ctx:=erp_private.plan_scope(p_actor,p_session,p_project,p_role);if (ctx->>'organization_id')::uuid<>p_org then raise exception 'Idegen szervezet.' using errcode='42501';end if;return ctx;end if;
 if p_role is distinct from 'office' or exists(select 1 from erp_private.client_accounts where auth_user_id=p_actor) or exists(select 1 from erp_private.staff_accounts where auth_user_id=p_actor) then raise exception 'Irodai hozzáférés szükséges.' using errcode='42501';end if;
 perform erp_private.require_customer_office(p_org,p_actor);select person_id into person from erp.user_accounts where organization_id=p_org and auth_user_id=p_actor and active;return jsonb_build_object('organization_id',p_org,'person_id',person,'role','office');end$$;
create function erp_private.material_plan_snapshot(p_plan uuid,p_actor uuid,p_role text,p_auth uuid default null) returns void language plpgsql security definer set search_path='' as $$declare p erp.project_material_plans;begin
 update erp.project_material_plans set revision=revision+1 where id=p_plan returning * into p;
 insert into erp.project_material_plan_versions(organization_id,plan_id,version,quote_version,document,actor_id,actor_auth_id,active_role) select p.organization_id,p.id,p.revision,p.quote_version,coalesce(jsonb_agg(to_jsonb(l) order by l.id),'[]'),p_actor,p_auth,p_role from erp.project_material_lines l where l.plan_id=p.id;
end$$;
create function erp_private.material_sync(p_project uuid,p_actor uuid,p_role text,p_auth uuid default null) returns void language plpgsql security definer set search_path='' as $$declare g erp.garden_projects;p erp.project_material_plans;q jsonb;s jsonb;l jsonb;m jsonb;slot int;k text;line erp.project_material_lines;master uuid;begin
 select * into g from erp.garden_projects where id=p_project for update;if g.work_type<>'construction' or g.accepted_quote_id is null then return;end if;
 select * into p from erp.project_material_plans where project_id=g.id;if p.id is null then insert into erp.project_material_plans(organization_id,project_id,quote_id,quote_version,created_by) values(g.organization_id,g.id,g.accepted_quote_id,g.accepted_quote_version,coalesce(p_auth,p_actor,g.created_by)) returning * into p;else update erp.project_material_plans set quote_id=g.accepted_quote_id,quote_version=g.accepted_quote_version where id=p.id;end if;
 select calculation into q from erp.quote_versions where organization_id=g.organization_id and quote_id=g.accepted_quote_id and version=g.accepted_quote_version;
 update erp.project_material_lines set active=false,installed_plan=0,purchase_plan=0 where plan_id=p.id and source_kind='quote';
 for s in select value from jsonb_array_elements(coalesce(q->'sections','[]')) loop for l in select value from jsonb_array_elements(coalesce(s->'lines','[]')) loop slot:=0;
 for m in select value from jsonb_array_elements(coalesce(l->'materials','[]')) loop slot:=slot+1;k:=(l->>'id')||'/'||slot||'/'||encode(sha256(convert_to((m->>'name')||'|'||(m->>'unit'),'UTF8')),'hex');
 select * into line from erp.project_material_lines where plan_id=p.id and source_key=k;
 master:=null;if m->>'material_id' ~ '^[a-f0-9-]{36}$' then select id into master from erp.materials where id=(m->>'material_id')::uuid and organization_id=g.organization_id and unit=m->>'unit' and active;end if;
 if line.id is null then insert into erp.project_material_lines(organization_id,plan_id,material_id,unit,name,source_kind,source_key,source_label,installed_plan,purchase_plan,original_installed,original_purchase,owner,expected_price,supplier,capacity,pack) values(g.organization_id,p.id,master,m->>'unit',m->>'name','quote',k,(s->>'name')||' / '||(l->>'label'),(m->>'installed')::numeric,(m->>'purchase')::numeric,(m->>'installed')::numeric,(m->>'purchase')::numeric,case when m->>'owner'='office' then 'office' else 'crew' end,nullif(m->>'unit_price','')::numeric,coalesce(m->>'supplier',''),coalesce(nullif(m->>'capacity','')::numeric,0),coalesce(nullif(m->>'pack','')::numeric,0));
 else update erp.project_material_lines set installed_plan=(m->>'installed')::numeric,purchase_plan=(m->>'purchase')::numeric,active=true,revision=revision+1,source_label=(s->>'name')||' / '||(l->>'label') where id=line.id;end if;
 end loop;end loop;end loop;
 perform erp_private.material_plan_snapshot(p.id,p_actor,p_role,p_auth);
end$$;
create function erp_private.material_quote_changed() returns trigger language plpgsql security definer set search_path='' as $$declare actor uuid;person uuid;begin if new.accepted_quote_id is not null and (tg_op='INSERT' or new.accepted_quote_id is distinct from old.accepted_quote_id or new.accepted_quote_version is distinct from old.accepted_quote_version) then select actor_id into actor from erp.quote_versions where organization_id=new.organization_id and quote_id=new.accepted_quote_id and version=new.accepted_quote_version;select person_id into person from erp.user_accounts where organization_id=new.organization_id and auth_user_id=actor and active;perform erp_private.material_sync(new.id,person,'system',actor);end if;return new;end$$;
create trigger material_quote_sync after insert or update of accepted_quote_id,accepted_quote_version on erp.garden_projects for each row execute function erp_private.material_quote_changed();

create function erp_private.material_number(p_text text,p_money boolean default false) returns numeric language plpgsql immutable set search_path='' as $$begin
 if p_text is null or p_text !~ '^[0-9]{1,16}(\.[0-9]{1,6})?$' or p_money and p_text !~ '^[0-9]{1,16}(\.[0-9]{1,2})?$' then raise exception 'Érvénytelen mennyiség vagy egységár.' using errcode='22023';end if;return p_text::numeric;end$$;
create function erp_private.material_prepare(p_ctx jsonb,p_command jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare org uuid:=(p_ctx->>'organization_id')::uuid;project uuid:=(p_ctx->'project'->>'id')::uuid;role text:=p_ctx->>'role';kind text:=p_command->>'kind';p erp.project_material_plans;l erp.project_material_lines;lot erp.material_lots;oldmove erp.material_movements;v erp.vendors;master erp.materials;policy erp.material_cost_policy_versions;data jsonb;before_state jsonb;after_state jsonb;delta jsonb:='{"ordered":0,"depot":0,"transit":0,"site":0,"installed":0}';q numeric:=0;value numeric;key text;newlot boolean:=false;warning text:='';target uuid;begin
 if jsonb_typeof(p_command) is distinct from 'object' or octet_length(p_command::text)>65536 or length(coalesce(p_command->>'reason',''))>4000 then raise exception 'Hiányos vagy túl nagy művelet.' using errcode='22023';end if;
 if kind in('material','vendor','policy','init','line','link') and role<>'office' or kind not in('material','vendor','policy','init','line','link') and role not in('office','construction_lead') then raise exception 'Ehhez a művelethez nincs jogosultságod.' using errcode='42501';end if;
 if project is null and kind not in('material','vendor','policy') or project is not null and kind in('material','vendor','policy') then raise exception 'Eltérő műveleti hatókör.' using errcode='22023';end if;
 if project is not null then
  if p_ctx->'project'->>'status' not in('waiting_start','running') or kind not in('init','line','link') and p_ctx->'project'->>'status'<>'running' then raise exception 'A kertépítés ebben az állapotban nem módosítható.' using errcode='42501';end if;
  select * into p from erp.project_material_plans where organization_id=org and project_id=project;
  if kind='init' then if p.id is not null then raise exception 'Az anyagterv már létezik.' using errcode='40001';end if;return jsonb_build_object('kind',kind,'quote_version',p_ctx->'project'->'quote_version','project',project);end if;
  if p.id is null or (p_command->>'plan_revision')::bigint is distinct from p.revision then raise exception 'Az anyagterv megváltozott. Frissítsd.' using errcode='40001';end if;
 end if;
 if kind='vendor' then
  target:=(p_command->>'id')::uuid;if exists(select 1 from erp.vendors where id=target and organization_id<>org) then raise exception 'Idegen beszállító.' using errcode='42501';end if;select * into v from erp.vendors where organization_id=org and id=target;
  if target is null or (p_command->>'revision')::bigint is distinct from coalesce(v.revision,0) then raise exception 'A beszállító megváltozott.' using errcode='40001';end if;
  if length(btrim(coalesce(p_command->>'name',''))) not between 1 and 200 or length(coalesce(p_command->>'place',''))>500 then raise exception 'Adj meg beszállítónevet és érvényes helyet.' using errcode='22023';end if;
  return jsonb_build_object('kind',kind,'before',to_jsonb(v),'after',jsonb_build_object('id',target,'name',btrim(p_command->>'name'),'place',btrim(coalesce(p_command->>'place','')),'active',coalesce((p_command->>'active')::boolean,true),'revision',coalesce(v.revision,0)+1));
 elsif kind='material' then
  target:=(p_command->>'id')::uuid;if exists(select 1 from erp.materials where id=target and organization_id<>org) then raise exception 'Idegen anyag.' using errcode='42501';end if;select * into master from erp.materials where organization_id=org and id=target;
  if target is null or (p_command->>'revision')::bigint is distinct from coalesce(master.revision,0) then raise exception 'Az anyagtörzs megváltozott.' using errcode='40001';end if;
  if length(btrim(coalesce(p_command->>'name',''))) not between 1 and 200 or length(btrim(coalesce(p_command->>'unit',''))) not between 1 and 30 then raise exception 'Adj meg anyagnevet és mértékegységet.' using errcode='22023';end if;
  if p_command->>'vendor_id' is not null and not exists(select 1 from erp.vendors where organization_id=org and id=(p_command->>'vendor_id')::uuid and active) then raise exception 'Idegen vagy inaktív beszállító.' using errcode='42501';end if;
  if master.id is not null and master.unit<>btrim(p_command->>'unit') and exists(select 1 from erp.project_material_lines where material_id=master.id) then raise exception 'Hivatkozott anyag mértékegysége nem cserélhető. Új törzsanyagot válassz.' using errcode='22023';end if;
  data:=jsonb_build_object('id',target,'name',btrim(p_command->>'name'),'unit',btrim(p_command->>'unit'),'vendor_id',p_command->'vendor_id','expected_price',case when p_command->>'expected_price' is null then null else erp_private.material_number(p_command->>'expected_price',true) end,'pack',erp_private.material_number(coalesce(p_command->>'pack','0')),'capacity',erp_private.material_number(coalesce(p_command->>'capacity','0')),'active',coalesce((p_command->>'active')::boolean,true),'revision',coalesce(master.revision,0)+1);
  return jsonb_build_object('kind',kind,'before',to_jsonb(master),'after',data);
 elsif kind='policy' then
  select * into policy from erp.material_cost_policy_versions where organization_id=org order by version desc limit 1;
  if (p_command->>'revision')::bigint is distinct from coalesce(policy.version,0) then raise exception 'A költségszabály megváltozott.' using errcode='40001';end if;
  data:='{}';foreach key in array array['installed','onsite','offsite'] loop value:=erp_private.material_number(p_command->>key);if value>100 or value<>round(value,4) then raise exception 'A súly 0–100%% közötti, legfeljebb négy tizedesű legyen.' using errcode='22023';end if;data:=data||jsonb_build_object(key,value);end loop;
  return jsonb_build_object('kind',kind,'before',to_jsonb(policy),'after',data||jsonb_build_object('version',coalesce(policy.version,0)+1));
 end if;
 select * into l from erp.project_material_lines where organization_id=org and plan_id=p.id and id=(p_command->>'line_id')::uuid;
 if kind='extra' then
  if length(btrim(coalesce(p_command->>'name',''))) not between 1 and 200 or length(btrim(coalesce(p_command->>'unit',''))) not between 1 and 30 or coalesce(p_command->>'extra_reason','') not in('customer','shortage') then raise exception 'Add meg az extra anyagot és indokát.' using errcode='22023';end if;
  value:=erp_private.material_number(p_command->>'quantity');if value<=0 then raise exception 'Pozitív mennyiség kell.' using errcode='22023';end if;
  if p_command->>'material_id' is not null and not exists(select 1 from erp.materials where organization_id=org and id=(p_command->>'material_id')::uuid and unit=p_command->>'unit' and active) then raise exception 'Eltérő törzsanyag vagy mértékegység.' using errcode='42501';end if;
  if (p_command->>'id')::uuid is null or exists(select 1 from erp.project_material_lines where id=(p_command->>'id')::uuid) then raise exception 'Az extra már létezik.' using errcode='40001';end if;
  return jsonb_build_object('kind',kind,'after',jsonb_build_object('id',p_command->'id','name',btrim(p_command->>'name'),'unit',btrim(p_command->>'unit'),'material_id',p_command->'material_id','quantity',value,'extra_reason',p_command->>'extra_reason','supplier',left(coalesce(p_command->>'supplier',''),500),'expected_price',case when p_command->>'expected_price' is null then null else erp_private.material_number(p_command->>'expected_price',true) end));
 end if;
 if l.id is null then raise exception 'Ez nem a projekt anyagsora.' using errcode='42501';end if;
 if kind='line' then
  if (p_command->>'revision')::bigint is distinct from l.revision then raise exception 'Az anyagsor megváltozott.' using errcode='40001';end if;
  if p_command->>'material_id' is not null and not exists(select 1 from erp.materials where organization_id=org and id=(p_command->>'material_id')::uuid and unit=l.unit and active) then raise exception 'Eltérő törzsanyag vagy mértékegység.' using errcode='42501';end if;
  if p_command->>'owner' not in('office','crew') then raise exception 'Válassz beszerzési felelőst.' using errcode='22023';end if;
  return jsonb_build_object('kind',kind,'before',to_jsonb(l),'after',jsonb_build_object('material_id',p_command->'material_id','owner',p_command->>'owner'));
 end if;
 if kind='link' then
  if l.source_kind<>'extra' or not l.active or not exists(select 1 from erp.project_material_lines x where x.id=(p_command->>'target_line_id')::uuid and x.plan_id=p.id and x.source_kind='quote' and x.active and x.unit=l.unit and (x.material_id=l.material_id or x.material_id is null or l.material_id is null)) then raise exception 'Csak azonos egységű extra kapcsolható aktív ajánlati anyaghoz.' using errcode='22023';end if;
  return jsonb_build_object('kind',kind,'before',to_jsonb(l),'after',p_command->'target_line_id');
 end if;
 if l.linked_line_id is not null then raise exception 'Az extra már másik anyagsorhoz kapcsolódik.' using errcode='40001';end if;
 select * into lot from erp.material_lots where organization_id=org and id=(p_command->>'lot_id')::uuid;
 if lot.id is null then
  if kind not in('order','receive_depot','receive_site') or not l.active or (p_command->>'revision')::bigint is distinct from 0::bigint or (p_command->>'lot_id')::uuid is null then raise exception 'Az új szállítmány nem érvényes.' using errcode='22023';end if;
  newlot:=true;lot.id:=(p_command->>'lot_id')::uuid;lot.organization_id:=org;lot.line_id:=l.id;lot.revision:=0;lot.ordered:=0;lot.depot:=0;lot.transit:=0;lot.site:=0;lot.installed:=0;lot.expected_price:=l.expected_price;lot.created_by:=(p_ctx->>'person_id')::uuid;
  lot.vendor_id:=(p_command->>'vendor_id')::uuid;if lot.vendor_id is not null and not exists(select 1 from erp.vendors where organization_id=org and id=lot.vendor_id and active) then raise exception 'Idegen beszállító.' using errcode='42501';end if;
  lot.place:=coalesce(p_command->>'place',l.supplier);if length(lot.place)>500 then raise exception 'Túl hosszú beszerzési hely.' using errcode='22023';end if;
  if p_command->>'actual_price' is not null then lot.actual_price:=erp_private.material_number(p_command->>'actual_price',true);lot.price_actor:=(p_ctx->>'person_id')::uuid;end if;
 else if lot.line_id<>l.id then raise exception 'Idegen szállítmány.' using errcode='42501';end if;if (p_command->>'revision')::bigint is distinct from lot.revision then raise exception 'A szállítmány megváltozott.' using errcode='40001';end if;end if;
 if role='construction_lead' and l.owner='office' and kind in('order','receive_depot','receive_site') then raise exception 'Ezt az anyagot az iroda szerzi be.' using errcode='42501';end if;
 before_state:=to_jsonb(lot);after_state:=before_state;
 if not newlot and kind in('receive_depot','receive_site') and lot.actual_price is null and p_command->>'actual_price' is not null and (role='office' or lot.created_by=(p_ctx->>'person_id')::uuid) then after_state:=after_state||jsonb_build_object('actual_price',erp_private.material_number(p_command->>'actual_price',true),'price_actor',p_ctx->'person_id');end if;
 if p_command->>'work_date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or (p_command->>'work_date')::date is null then raise exception 'Érvénytelen munkanap.' using errcode='22023';end if;
 if kind='price' then
  if role<>'office' then raise exception 'Tényleges árat csak az iroda korrigálhat.' using errcode='42501';end if;
  after_state:=after_state||jsonb_build_object('actual_price',case when p_command->>'actual_price' is null then null else erp_private.material_number(p_command->>'actual_price',true) end,'price_actor',p_ctx->'person_id');
 elsif kind='reverse' then
  if length(btrim(coalesce(p_command->>'reason','')))=0 then raise exception 'A visszavonás indoka kötelező.' using errcode='22023';end if;
  select * into oldmove from erp.material_movements where organization_id=org and lot_id=lot.id and id=(p_command->>'reverses_id')::uuid;
  if role='construction_lead' and l.owner='office' and oldmove.kind in('order','receive_depot','receive_site','price') then raise exception 'Az irodai beszerzést az iroda korrigálhatja.' using errcode='42501';end if;
  if oldmove.id is null or exists(select 1 from erp.material_movements where reverses_id=oldmove.id) then raise exception 'A mozgás már visszavont vagy nem elérhető.' using errcode='40001';end if;
  if oldmove.kind='price' or oldmove.before_state->'actual_price' is distinct from oldmove.after_state->'actual_price' and oldmove.kind='reverse' then
   if role<>'office' or before_state->'actual_price' is distinct from oldmove.after_state->'actual_price' then raise exception 'Az árkorrekció időközben megváltozott.' using errcode='40001';end if;after_state:=after_state||jsonb_build_object('actual_price',oldmove.before_state->'actual_price','price_actor',p_ctx->'person_id');
  end if;
  foreach key in array array['ordered','depot','transit','site','installed'] loop delta:=jsonb_set(delta,array[key],to_jsonb(-(oldmove.delta->>key)::numeric));end loop;
 else
  q:=erp_private.material_number(p_command->>'quantity');if q<=0 then raise exception 'Pozitív mennyiség kell.' using errcode='22023';end if;
  case kind when 'order' then delta:=jsonb_set(delta,'{ordered}',to_jsonb(q));when 'receive_depot' then delta:=jsonb_set(delta,'{depot}',to_jsonb(q));when 'receive_site' then delta:=jsonb_set(delta,'{site}',to_jsonb(q));when 'pickup' then delta:=delta||jsonb_build_object('depot',-q,'transit',q);when 'deliver' then delta:=delta||jsonb_build_object('transit',-q,'site',q);when 'install' then delta:=delta||jsonb_build_object('site',-q,'installed',q);when 'return_depot' then delta:=delta||jsonb_build_object('site',-q,'depot',q);else raise exception 'Ismeretlen anyagmozgás.' using errcode='22023';end case;
 end if;
 foreach key in array array['ordered','depot','transit','site','installed'] loop value:=(before_state->>key)::numeric+(delta->>key)::numeric;if value<0 then raise exception 'Nincs elegendő szabad anyag; előbb rendezd a későbbi mozgásokat.' using errcode='22023';end if;after_state:=jsonb_set(after_state,array[key],to_jsonb(value));end loop;
 if kind in('order','receive_depot','receive_site','install') then
  select coalesce(sum(case when kind='order' then x.ordered when kind='install' then x.installed else x.depot+x.transit+x.site+x.installed end),0) into value from erp.material_lots x where x.line_id=l.id and x.id<>lot.id;
  value:=value+case when kind='order' then (after_state->>'ordered')::numeric when kind='install' then (after_state->>'installed')::numeric else (after_state->>'depot')::numeric+(after_state->>'transit')::numeric+(after_state->>'site')::numeric+(after_state->>'installed')::numeric end;
  if value>(case when kind='install' then l.installed_plan else l.purchase_plan end) then warning:='A tényleges mennyiség meghaladja a tervet. Ellenőrzés után külön erősítsd meg.';end if;
 end if;
 return jsonb_build_object('kind',kind,'new_lot',newlot,'before',before_state,'after',after_state,'delta',delta,'quantity',q,'line',to_jsonb(l),'warning',warning);
end$$;

create function erp_private.material_policy(p_org uuid) returns jsonb language sql stable security definer set search_path='' as $$select coalesce((select to_jsonb(p) from erp.material_cost_policy_versions p where organization_id=p_org order by version desc limit 1),'{"version":0,"installed":100,"onsite":70,"offsite":0}'::jsonb)$$;
create function erp_private.material_line_view(p_id uuid,p_role text) returns jsonb language plpgsql stable security definer set search_path='' as $$declare l erp.project_material_lines;q record;r jsonb;begin
 select * into l from erp.project_material_lines where id=p_id;
 select coalesce(sum(ordered),0) ordered,coalesce(sum(depot),0) depot,coalesce(sum(transit),0) transit,coalesce(sum(site),0) site,coalesce(sum(installed),0) installed from erp.material_lots where line_id=l.id into q;
 r:=jsonb_build_object('id',l.id,'material_id',l.material_id,'revision',l.revision,'name',l.name,'unit',l.unit,'source_kind',l.source_kind,'source_label',l.source_label,'active',l.active,'linked_line_id',l.linked_line_id,'installed_plan',l.installed_plan::text,'original_installed',l.original_installed::text,'installed',q.installed::text,'installed_percent',case when l.installed_plan>0 then round(q.installed/l.installed_plan*100,2)::text else null end);
 if p_role<>'client' then r:=r||jsonb_build_object('purchase_plan',l.purchase_plan::text,'original_purchase',l.original_purchase::text,'ordered',q.ordered::text,'depot',q.depot::text,'transit',q.transit::text,'site',q.site::text,'received',(q.depot+q.transit+q.site+q.installed)::text,'delivered',(q.site+q.installed)::text,'picked',(q.transit+q.site+q.installed)::text,'owner',l.owner,'reason',l.reason,'received_percent',case when l.purchase_plan>0 then round((q.depot+q.transit+q.site+q.installed)/l.purchase_plan*100,2)::text else null end,'delivered_percent',case when l.purchase_plan>0 then round((q.site+q.installed)/l.purchase_plan*100,2)::text else null end);end if;
 if p_role in('office','construction_lead') then r:=r||jsonb_build_object('expected_price',l.expected_price::text,'supplier',l.supplier,'capacity',l.capacity::text,'pack',l.pack::text,'trips',case when l.capacity>0 then ceil(l.purchase_plan/l.capacity)::text else null end);end if;return r;
end$$;
create function erp_private.material_cost(p_org uuid,p_project uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare w jsonb;g erp.garden_projects;quoted numeric;spent numeric;charged numeric;missing int;begin
 w:=erp_private.material_policy(p_org);select * into g from erp.garden_projects where id=p_project and organization_id=p_org;select (calculation->>'material')::numeric into quoted from erp.quote_versions where organization_id=p_org and quote_id=g.accepted_quote_id and version=g.accepted_quote_version;
 select coalesce(sum((x.depot+x.transit+x.site+x.installed)*x.actual_price),0),coalesce(sum((x.installed*(w->>'installed')::numeric+x.site*(w->>'onsite')::numeric+(x.depot+x.transit)*(w->>'offsite')::numeric)/100*x.actual_price),0),count(*) filter(where x.actual_price is null and x.depot+x.transit+x.site+x.installed>0) into spent,charged,missing from erp.material_lots x join erp.project_material_lines l on l.id=x.line_id join erp.project_material_plans p on p.id=l.plan_id where p.project_id=p_project and p.organization_id=p_org;
 return jsonb_build_object('policy',w,'quoted',quoted::text,'purchased',round(spent,2)::text,'charged',round(charged,2)::text,'missing_prices',missing,'complete',missing=0,'difference',case when missing=0 and quoted is not null then round(quoted-charged,2)::text else null end);
end$$;
create function erp_private.material_findtext(p_text text) returns text language sql immutable set search_path='' as $$select translate(lower(p_text),'áéíóöőúüű','aeiooouuu')$$;
create function public.erp_material_read(p_org uuid,p_actor uuid,p_session uuid,p_project uuid,p_role text,p_filter jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path='' as $$
declare ctx jsonb;p erp.project_material_plans;rows jsonb;lots jsonb:='[]';events jsonb:='[]';groups jsonb:='[]';masters jsonb:='[]';vendors jsonb:='[]';notes jsonb;query text:=erp_private.material_findtext(coalesce(p_filter->>'query',''));selected uuid:=(p_filter->>'line_id')::uuid;selected_lot uuid:=(p_filter->>'lot_id')::uuid;person uuid;summary jsonb;result jsonb;begin
 ctx:=erp_private.material_context(p_org,p_actor,p_session,p_project,p_role);person:=(ctx->>'person_id')::uuid;
 if length(query)>200 or length(query)=1 then raise exception 'A keresés legalább két karakter legyen.' using errcode='22023';end if;
 if p_project is not null then select * into p from erp.project_material_plans where organization_id=p_org and project_id=p_project;end if;
 select coalesce(jsonb_agg(x.doc order by x.name,x.id),'[]') into rows from(select l.id,l.name,erp_private.material_line_view(l.id,p_role) doc from erp.project_material_lines l where l.plan_id=p.id and (selected is null or l.id=selected) and (p_role<>'client' or l.active and l.source_kind='quote') and (p_filter->>'show_archived'='true' or l.active or exists(select 1 from erp.material_lots z where z.line_id=l.id)) and (query='' or position(query in erp_private.material_findtext(l.name))>0) and (p_filter->'after_line'->>'id' is null or (l.name,l.id)>(p_filter->'after_line'->>'name',(p_filter->'after_line'->>'id')::uuid)) order by l.name,l.id limit 100)x;

 if p_role<>'client' then
 with balances as(select line_id,sum(depot) depot,sum(transit) transit,sum(site) site,sum(installed) installed from erp.material_lots group by line_id),grouped as(select coalesce(l.material_id,l.id) id,max(coalesce(m.name,l.name)) name,l.unit,sum(l.installed_plan) installed_plan,sum(l.purchase_plan) purchase_plan,sum(coalesce(b.depot,0)) depot,sum(coalesce(b.transit,0)) transit,sum(coalesce(b.site,0)) site,sum(coalesce(b.installed,0)) installed,bool_and(l.material_id is not null) mapped from erp.project_material_lines l left join erp.materials m on m.id=l.material_id left join balances b on b.line_id=l.id where l.plan_id=p.id and (l.active or b.line_id is not null) and (query='' or position(query in erp_private.material_findtext(coalesce(m.name,l.name)))>0) group by coalesce(l.material_id,l.id),l.unit)
 select coalesce(jsonb_agg(to_jsonb(x) order by x.name,x.id),'[]') into groups from(select g.id,g.name,g.unit,g.installed_plan::text,g.purchase_plan::text,g.depot::text,g.transit::text,g.site::text,g.installed::text,(g.depot+g.transit+g.site+g.installed)::text received,g.mapped from grouped g where p_filter->'after_group'->>'id' is null or (g.name,g.id)>(p_filter->'after_group'->>'name',(p_filter->'after_group'->>'id')::uuid) order by g.name,g.id limit 100)x;
 end if;
 if selected is not null and not exists(select 1 from erp.project_material_lines where id=selected and plan_id=p.id) or selected_lot is not null and not exists(select 1 from erp.material_lots a join erp.project_material_lines b on b.id=a.line_id where a.id=selected_lot and b.plan_id=p.id) then raise exception 'Idegen anyag vagy szállítmány.' using errcode='42501';end if;
 if p_role in('office','construction_lead') then
  select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') into lots from(select a.id,a.line_id,a.revision,a.vendor_id,a.place,a.expected_price::text,case when p_role='office' or a.price_actor=person then a.actual_price::text else null end actual_price,(p_role='office' or a.price_actor=person) as price_visible,a.ordered::text,a.depot::text,a.transit::text,a.site::text,a.installed::text,a.created_by,a.created_at,l.name,l.unit from erp.material_lots a join erp.project_material_lines l on l.id=a.line_id where l.plan_id=p.id and (selected is null or l.id=selected) and (selected_lot is null or a.id=selected_lot) and (p_filter->>'after_lot' is null or a.id>(p_filter->>'after_lot')::uuid) order by a.id limit 100)x;
  select coalesce(jsonb_agg(x.doc order by x.created_at desc,x.id desc),'[]') into events from(select e.id,e.created_at,jsonb_build_object('id',e.id,'lot_id',e.lot_id,'kind',e.kind,'quantity',e.quantity::text,'delta',e.delta,'actor_name',n.display_name,'role',e.active_role,'work_date',e.work_date,'created_at',e.created_at,'reason',e.reason,'reverses_id',e.reverses_id,'reversed_by',(select id from erp.material_movements r where r.reverses_id=e.id),'actual_price',case when p_role='office' or (e.after_state->>'price_actor')::uuid=person then e.after_state->'actual_price' else null end,'line_id',l.id,'name',l.name,'unit',l.unit) doc from erp.material_movements e join erp.material_lots a on a.id=e.lot_id join erp.project_material_lines l on l.id=a.line_id join erp.persons n on n.id=e.actor_id where l.plan_id=p.id and (selected is null or l.id=selected) and (selected_lot is null or e.lot_id=selected_lot) and (p_filter->'before_event'->>'id' is null or (e.created_at,e.id)<((p_filter->'before_event'->>'time')::timestamptz,(p_filter->'before_event'->>'id')::uuid)) order by e.created_at desc,e.id desc limit 100)x;
  select coalesce(jsonb_agg(to_jsonb(x) order by x.name,x.id),'[]') into masters from(select a.id,a.name,a.unit,a.vendor_id,(select name from erp.vendors where id=a.vendor_id) vendor_name,a.expected_price::text,a.pack::text,a.capacity::text,a.active,a.revision from erp.materials a where organization_id=p_org and (p_filter->>'master_id' is null or a.id=(p_filter->>'master_id')::uuid) and (a.active or p_role='office') and (query='' or position(query in erp_private.material_findtext(a.name))>0) and (p_filter->'after_master'->>'id' is null or (a.name,a.id)>(p_filter->'after_master'->>'name',(p_filter->'after_master'->>'id')::uuid)) order by a.name,a.id limit 100)x;
  select coalesce(jsonb_agg(to_jsonb(x) order by x.name,x.id),'[]') into vendors from(select a.* from erp.vendors a where organization_id=p_org and (p_filter->>'vendor_id' is null or a.id=(p_filter->>'vendor_id')::uuid) and (a.active or p_role='office') and (query='' or position(query in erp_private.material_findtext(a.name))>0) and (p_filter->'after_vendor'->>'id' is null or (a.name,a.id)>(p_filter->'after_vendor'->>'name',(p_filter->'after_vendor'->>'id')::uuid)) order by a.name,a.id limit 100)x;
 end if;
 select jsonb_build_object('line_count',count(*),'unmapped',count(*) filter(where material_id is null),'extra_count',count(*) filter(where source_kind='extra' and active)) into summary from erp.project_material_lines where plan_id=p.id and (p_role<>'client' or active and source_kind='quote');
 result:=jsonb_build_object('context',jsonb_build_object('person_id',person,'role',p_role,'project',ctx->'project','can_write',p_role in('office','construction_lead') and ctx->'project'->>'status'='running','can_plan',p_role='office' and ctx->'project'->>'status' in('waiting_start','running')),'plan',case when p.id is null then null else jsonb_build_object('id',p.id,'revision',p.revision,'quote_id',p.quote_id,'quote_version',p.quote_version) end,'summary',summary,'purchase_groups',groups,'lines',rows,'lots',lots,'events',events,'materials',masters,'vendors',vendors,'cursors',jsonb_build_object('group',case when jsonb_array_length(groups)=100 then jsonb_build_object('name',groups->-1->>'name','id',groups->-1->>'id') else null end,'line',case when jsonb_array_length(rows)=100 then jsonb_build_object('name',rows->-1->>'name','id',rows->-1->>'id') else null end,'lot',case when jsonb_array_length(lots)=100 then lots->-1->>'id' else null end,'event',case when jsonb_array_length(events)=100 then jsonb_build_object('time',events->-1->>'created_at','id',events->-1->>'id') else null end,'master',case when jsonb_array_length(masters)=100 then jsonb_build_object('name',masters->-1->>'name','id',masters->-1->>'id') else null end,'vendor',case when jsonb_array_length(vendors)=100 then jsonb_build_object('name',vendors->-1->>'name','id',vendors->-1->>'id') else null end));
 if p_role='office' then
  result:=result||jsonb_build_object('policy',erp_private.material_policy(p_org),'cost',case when p.id is null then null else erp_private.material_cost(p_org,p_project) end,'versions',coalesce((select jsonb_agg(x.doc order by x.version desc) from(select z.version,jsonb_build_object('version',z.version,'quote_version',z.quote_version,'created_at',z.created_at,'role',z.active_role) doc from erp.project_material_plan_versions z where z.plan_id=p.id and (p_filter->>'before_version' is null or z.version<(p_filter->>'before_version')::bigint) order by z.version desc limit 100)x),'[]'),'history',case when p_filter->>'plan_version' is null then null else (select document from erp.project_material_plan_versions where plan_id=p.id and version=(p_filter->>'plan_version')::bigint) end);
  result:=result||jsonb_build_object('catalog_events',coalesce((select jsonb_agg(x.doc order by x.created_at desc,x.id desc) from(select e.id,e.created_at,jsonb_build_object('id',e.id,'kind',e.kind,'created_at',e.created_at,'actor_name',n.display_name,'role',e.active_role,'document',e.document) doc from erp.material_catalog_events e join erp.persons n on n.id=e.actor_id where e.organization_id=p_org and (e.document->>'project_id')::uuid is not distinct from p_project and (p_filter->'before_catalog'->>'id' is null or (e.created_at,e.id)<((p_filter->'before_catalog'->>'time')::timestamptz,(p_filter->'before_catalog'->>'id')::uuid)) order by e.created_at desc,e.id desc limit 100)x),'[]'));
  if p_project is null then result:=result||jsonb_build_object('projects',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'address',g.site_address,'status',g.work_status) order by g.name,g.id) from erp.garden_projects g where g.organization_id=p_org and g.work_type='construction' and g.accepted_quote_id is not null),'[]'));end if;
 end if;
 if p_role='office' then result:=result||jsonb_build_object('version_cursor',case when jsonb_array_length(result->'versions')=100 then result->'versions'->-1->'version' else null end,'catalog_cursor',case when jsonb_array_length(result->'catalog_events')=100 then jsonb_build_object('time',result->'catalog_events'->-1->>'created_at','id',result->'catalog_events'->-1->>'id') else null end);end if;
 return result;
end$$;
create function public.erp_material_preview(p_org uuid,p_actor uuid,p_session uuid,p_project uuid,p_role text,p_command jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$declare ctx jsonb;data jsonb;token text;begin
 ctx:=erp_private.material_context(p_org,p_actor,p_session,p_project,p_role);data:=erp_private.material_prepare(ctx,p_command);token:=encode(sha256(convert_to(jsonb_build_object('actor',p_actor,'role',p_role,'org',p_org,'project',p_project,'command',p_command-'exceed_accepted','data',data)::text,'UTF8')),'hex');
 return jsonb_build_object('token',token,'document',data,'person_id',ctx->'person_id');
end$$;

create function public.erp_material_write(p_org uuid,p_actor uuid,p_session uuid,p_project uuid,p_role text,p_request uuid,p_fingerprint text,p_command jsonb,p_preview text,p_confirmed boolean) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare ctx jsonb;person uuid;prior record;review jsonb;d jsonb;a jsonb;b jsonb;result jsonb;kind text:=p_command->>'kind';v_plan uuid;v_lot uuid;v_line uuid;lock_id uuid;begin
 ctx:=erp_private.material_context(p_org,p_actor,p_session,p_project,p_role);person:=(ctx->>'person_id')::uuid;
 if p_request is null or p_fingerprint is null or p_fingerprint !~ '^[a-f0-9]{64}$' or p_confirmed is not true then raise exception 'Hiányos vagy nem megerősített mentés.' using errcode='22023';end if;
 if p_project is null then perform 1 from erp.organizations where id=p_org for update;else perform 1 from erp.garden_projects where id=p_project and organization_id=p_org for update;end if;
 select e.actor_auth_id,e.active_role,e.request_hash,e.result,e.organization_id,l.plan_id into prior from erp.material_movements e join erp.material_lots t on t.id=e.lot_id join erp.project_material_lines l on l.id=t.line_id where e.id=p_request;
 if not found then select e.actor_auth_id,e.active_role,e.request_hash,e.result,e.organization_id,(select id from erp.project_material_plans where project_id=(e.document->>'project_id')::uuid) as plan_id into prior from erp.material_catalog_events e where e.id=p_request;end if;
 if found then if prior.actor_auth_id<>p_actor or prior.active_role<>p_role or prior.organization_id<>p_org or prior.request_hash<>p_fingerprint or p_project is not null and not exists(select 1 from erp.project_material_plans p where p.id=prior.plan_id and p.project_id=p_project) then raise exception 'Eltérő ismételt kérés.' using errcode='40001';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 ctx:=erp_private.material_context(p_org,p_actor,p_session,p_project,p_role);
 if p_project is not null then select id into v_plan from erp.project_material_plans where project_id=p_project;end if;
 for lock_id in select t.id from erp.material_lots t join erp.project_material_lines l on l.id=t.line_id where l.plan_id=v_plan and (t.id=(p_command->>'lot_id')::uuid or kind='link' and l.id=(p_command->>'line_id')::uuid) order by t.id for update of t loop null;end loop;
 review:=public.erp_material_preview(p_org,p_actor,p_session,p_project,p_role,p_command);
 if p_preview is null or p_preview is distinct from review->>'token' then raise exception 'Az előnézet megváltozott. Ellenőrizd újra.' using errcode='40001';end if;
 d:=review->'document';a:=d->'after';b:=d->'before';if coalesce(d->>'warning','')<>'' and coalesce((p_command->>'exceed_accepted')::boolean,false) is not true then raise exception 'A terv túllépését külön meg kell erősíteni.' using errcode='22023';end if;
 case kind
 when 'init' then perform erp_private.material_sync(p_project,person,p_role,p_actor);
 when 'vendor' then insert into erp.vendors(id,organization_id,name,place,active,revision) values((a->>'id')::uuid,p_org,a->>'name',a->>'place',(a->>'active')::boolean,(a->>'revision')::bigint) on conflict(id) do update set name=excluded.name,place=excluded.place,active=excluded.active,revision=excluded.revision;
 when 'material' then insert into erp.materials(id,organization_id,name,unit,vendor_id,expected_price,pack,capacity,active,revision) values((a->>'id')::uuid,p_org,a->>'name',a->>'unit',(a->>'vendor_id')::uuid,(a->>'expected_price')::numeric,(a->>'pack')::numeric,(a->>'capacity')::numeric,(a->>'active')::boolean,(a->>'revision')::bigint) on conflict(id) do update set name=excluded.name,unit=excluded.unit,vendor_id=excluded.vendor_id,expected_price=excluded.expected_price,pack=excluded.pack,capacity=excluded.capacity,active=excluded.active,revision=excluded.revision;
 when 'policy' then insert into erp.material_cost_policy_versions(organization_id,version,installed,onsite,offsite,actor_id,reason) values(p_org,(a->>'version')::bigint,(a->>'installed')::numeric,(a->>'onsite')::numeric,(a->>'offsite')::numeric,person,coalesce(p_command->>'reason',''));
 when 'extra' then
  insert into erp.project_material_lines(id,organization_id,plan_id,material_id,unit,name,source_kind,installed_plan,purchase_plan,original_installed,original_purchase,owner,expected_price,supplier,reason) values((a->>'id')::uuid,p_org,v_plan,(a->>'material_id')::uuid,a->>'unit',a->>'name','extra',(a->>'quantity')::numeric,(a->>'quantity')::numeric,(a->>'quantity')::numeric,(a->>'quantity')::numeric,'crew',(a->>'expected_price')::numeric,a->>'supplier',(a->>'extra_reason')||': '||coalesce(p_command->>'reason',''));v_line:=(a->>'id')::uuid;perform erp_private.material_plan_snapshot(v_plan,person,p_role,p_actor);
 when 'line' then
  update erp.project_material_lines set material_id=(a->>'material_id')::uuid,owner=a->>'owner',revision=revision+1 where id=(b->>'id')::uuid;v_line:=(b->>'id')::uuid;perform erp_private.material_plan_snapshot(v_plan,person,p_role,p_actor);
 when 'link' then
  v_line:=(p_command->>'target_line_id')::uuid;update erp.material_lots set line_id=v_line,revision=revision+1 where line_id=(b->>'id')::uuid;
  update erp.project_material_lines set active=false,installed_plan=0,purchase_plan=0,linked_line_id=v_line,revision=revision+1 where id=(b->>'id')::uuid;perform erp_private.material_plan_snapshot(v_plan,person,p_role,p_actor);
 else
  v_lot:=(a->>'id')::uuid;v_line:=(a->>'line_id')::uuid;
  if (d->>'new_lot')::boolean then insert into erp.material_lots(id,organization_id,line_id,vendor_id,place,expected_price,actual_price,price_actor,created_by) values(v_lot,p_org,v_line,(a->>'vendor_id')::uuid,a->>'place',(a->>'expected_price')::numeric,(a->>'actual_price')::numeric,(a->>'price_actor')::uuid,person);end if;
  update erp.material_lots set ordered=(a->>'ordered')::numeric,depot=(a->>'depot')::numeric,transit=(a->>'transit')::numeric,site=(a->>'site')::numeric,installed=(a->>'installed')::numeric,actual_price=(a->>'actual_price')::numeric,price_actor=(a->>'price_actor')::uuid,revision=revision+1 where id=v_lot;
  result:=jsonb_build_object('success',true,'kind',kind,'lot_id',v_lot,'line_id',v_line);
  insert into erp.material_movements(id,organization_id,lot_id,actor_id,actor_auth_id,active_role,kind,work_date,quantity,delta,before_state,after_state,reverses_id,reason,request_hash,result) values(p_request,p_org,v_lot,person,p_actor,p_role,kind,(p_command->>'work_date')::date,(d->>'quantity')::numeric,d->'delta',b,a,(p_command->>'reverses_id')::uuid,coalesce(p_command->>'reason',''),p_fingerprint,result);
  if (d->'delta'->>'depot')::numeric>0 then
   insert into erp.material_notifications(organization_id,project_id,movement_id,recipient_id) select distinct p_org,p_project,p_request,x.person_id from erp.project_assignments x join erp.persons n on n.id=x.person_id where x.organization_id=p_org and x.project_id=p_project and x.role='construction_lead' and x.revoked_at is null and x.valid_from<=now() and (x.valid_until is null or x.valid_until>now()) and n.active on conflict(movement_id,recipient_id) do nothing;
  end if;
  if (a->>'depot')::numeric=0 then update erp.material_notifications set completed_at=coalesce(completed_at,clock_timestamp()) where movement_id in(select id from erp.material_movements where lot_id=v_lot);end if;
  return result;
 end case;
 result:=jsonb_build_object('success',true,'kind',kind,'line_id',v_line);
 insert into erp.material_catalog_events(id,organization_id,actor_id,actor_auth_id,active_role,kind,target_id,document,request_hash,result) values(p_request,p_org,person,p_actor,p_role,kind,coalesce((a->>'id')::uuid,v_line,p_project),d||jsonb_build_object('project_id',p_project),p_fingerprint,result);
 return result;
end$$;
create function public.erp_material_notifications(p_actor uuid,p_session uuid,p_notification uuid default null,p_before timestamptz default null,p_before_id uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$declare account record;ctx jsonb;result jsonb:='[]';n record;begin
 for account in select a.organization_id,a.person_id from erp.user_accounts a join erp.persons p on p.id=a.person_id where a.auth_user_id=p_actor and a.active and p.active loop
  for n in select x.*,a.line_id,a.depot,l.name,l.unit,l.plan_id from erp.material_notifications x join erp.material_movements m on m.id=x.movement_id join erp.material_lots a on a.id=m.lot_id join erp.project_material_lines l on l.id=a.line_id where x.organization_id=account.organization_id and x.recipient_id=account.person_id and (p_before is null or (x.created_at,x.id)<(p_before,p_before_id)) order by x.created_at desc,x.id desc limit 100 loop
   begin ctx:=erp_private.material_context(account.organization_id,p_actor,p_session,n.project_id,'construction_lead');exception when insufficient_privilege then continue;end;
   if n.id=p_notification then update erp.material_notifications set read_at=coalesce(read_at,clock_timestamp()) where id=n.id;end if;
   result:=result||jsonb_build_array(jsonb_build_object('id',n.id,'organization_id',account.organization_id,'project_id',n.project_id,'line_id',n.line_id,'material_id',n.id,'kind','material','role','construction_lead','name',n.name,'available',n.depot::text,'unit',n.unit,'created_at',n.created_at,'completed_at',n.completed_at));
  end loop;
 end loop;return (select coalesce(jsonb_agg(x.value order by x.value->>'created_at' desc,x.value->>'id' desc),'[]') from(select value from jsonb_array_elements(result) order by value->>'created_at' desc,value->>'id' desc limit 100)x);
end$$;
do $$declare f record;begin for f in select p.oid::regprocedure signature,n.nspname,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='erp_private' and p.proname like 'material_%') or (n.nspname='public' and p.proname like 'erp_material_%') loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);if f.nspname='public' then execute format('grant execute on function %s to service_role',f.signature);end if;end loop;end$$;
commit;
